const body = $input.first().json.body || $input.first().json;
const action = body.action || (body.pregunta ? 'responder_pregunta' : 'generar_descripcion');

let prompt = '';
if (action === 'generar_descripcion') {
  const p = body.producto || {};
  prompt = `Genera una descripción comercial persuasiva y técnica para el producto de tecnología:
Nombre: ${p.nombre || 'Producto'}
Categoría: ${p.categoria || 'Tecnología'}

Devuelve OBLIGATORIAMENTE un JSON estrictamente válido con este esquema:
{
  "copy_comercial": "texto persuasivo de 2 a 3 oraciones destacando valor y especificaciones",
  "puntos_clave": ["característica 1", "característica 2", "característica 3"],
  "recomendados": ["Producto complementario 1", "Producto complementario 2"]
}`;
} else if (action === 'recomendar_carrito') {
  const items = body.items || [];
  const listaNombres = items.map(i => `${i.nombre} (${i.categoria || 'General'})`).join(', ');
  prompt = `El cliente tiene los siguientes artículos en su carrito de compras de tecnología:
${listaNombres || 'Sin productos aún'}

Analiza estos artículos y sugiere exactamente 2 o 3 productos complementarios ideales del catálogo de tecnología (ejemplos: Mouse Pad XL, Soporte para Laptop, Cable HDMI 4K, Disco SSD NVMe, Auriculares, Webcam 1080p).

Devuelve OBLIGATORIAMENTE un JSON estrictamente válido con este esquema:
{
  "analisis_carrito": "breve diagnóstico de 1 o 2 oraciones sobre lo que está armando el cliente",
  "recomendados": [
    {
      "nombre": "Nombre del producto",
      "justificacion": "Por qué complementa perfectamente su compra"
    }
  ]
}`;
} else if (action === 'responder_pregunta' || action === 'chat' || body.pregunta) {
  const pregunta = body.pregunta || body.prompt || body.mensaje || 'Información de hardware';
  const pActual = body.producto ? `Producto en vista: ${body.producto.nombre} (${body.producto.categoria}) - Precio: ₡${body.producto.precio}` : 'Catálogo general de CyberForge Hardware';
  prompt = `Eres el Agente Inteligente Copiloto de CyberForge Hardware. El cliente pregunta:
"${pregunta}"

Contexto:
${pActual}
Productos disponibles: Mouse Gamer Óptico (₡22.000, 24 stock), Teclado Mecánico RGB (₡45.000), Monitor 27 Pulgadas 144Hz (₡165.000), Headset Inalámbrico Pro (₡55.000), Mouse Pad XL (₡12.000), Memoria RAM 16GB DDR4 (₡32.000), Disco SSD NVMe 1TB (₡58.000), Laptop Ultrabook 14" (₡520.000).
Cupones: SUPERTECH20 (20%), DESCUENTO10 (10%).
Envíos: San José ₡2.000, GAM ₡3.500, Otras ₡5.000. Gratis si supera ₡35.000.

Responde en tono profesional, amigable y con conocimiento técnico.
Devuelve OBLIGATORIAMENTE un JSON estrictamente válido con este esquema:
{
  "respuesta": "tu respuesta persuasiva y detallada",
  "sugerencias": ["Pregunta sugerida 1", "Pregunta sugerida 2"],
  "producto_recomendado": "Nombre de producto relevante"
}`;
} else {
  prompt = `Devuelve un JSON con: {"mensaje": "Acción no reconocida"}`;
}

return [{
  json: {
    action,
    prompt,
    originalBody: body
  }
}];

const item = $input.first().json;
let rawOutput = item.output || item.text || '';
let dataParsed = null;
let errorMsg = null;

try {
  // Limpieza de formato markdown si el modelo incluyó ```json
  let cleanText = String(rawOutput).trim();
  if (cleanText.startsWith('```')) {
    cleanText = cleanText.replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/```$/i, '').trim();
  }
  dataParsed = JSON.parse(cleanText);
} catch (e) {
  // Si falla el parseo, entregar texto plano encapsulado
  dataParsed = {
    resultado_texto: rawOutput
  };
}

// Contrato estricto requerido por el laboratorio
return [{
  json: {
    ok: true,
    data: dataParsed,
    error: null
  }
}];
